# -*- coding: utf-8 -*-
"""Static local two-stage image retrieval demo, using locked numeric features."""
import base64,json,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
import numpy as np
out=ROOT/'outputs/sticker-semantic-v3-local-20261118';data=json.loads((out/'full-dataset.json').read_text());rows=data['rows'];feat=np.load(out/'evaluation-features.npz');style=np.load(out/'all-style-features.npz')
if list(feat['ids'])!=list(style['ids']):raise ValueError('IDs differ')
semantic=np.clip(feat['v3_image']@feat['v3_image'].T,-1,1);distance=np.clip(1-style['style']@style['style'].T,0,2)
def encode(a):return base64.b64encode(np.rint(a*10000).astype('<i2').tobytes()).decode()
key=json.loads((out/'top5-researcher-key.json').read_text());exclude={}
audit=json.loads((ROOT/'outputs/sticker-codex-local-20261118/full-split-audit.json').read_text())
for a,b in audit['near_duplicate_links']:
 exclude.setdefault(a,[]).append(b);exclude.setdefault(b,[]).append(a)
meta=[{'id':r['id'],'text':r['text'],'quality':r['quality'],'split':r['split']} for r in rows]
page='''<!doctype html><html lang="zh"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>小屿 · 本地表情包检索测试</title><style>*{box-sizing:border-box}body{margin:0;background:#f2f5f1;color:#263e36;font:16px system-ui;line-height:1.6}main{max-width:1250px;margin:auto;padding:28px}header,.panel,section{background:white;border-radius:18px;padding:24px;margin-bottom:20px}h1{margin:0}h2{margin:8px 0}p{color:#53685d}.controls{display:flex;gap:16px;flex-wrap:wrap;align-items:center}.controls>label{min-width:0;max-width:100%;flex:1 1 280px}.controls select{max-width:100%;width:100%;min-width:0}.query>div{min-width:0;overflow-wrap:anywhere}select,input{padding:10px;font:inherit;border:1px solid #b8cdbf;border-radius:9px}.query{display:flex;gap:24px;margin-top:20px;align-items:center}.query img{width:150px;height:150px;object-fit:contain}.grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px}.card{background:#f4f6f2;border-radius:12px;padding:12px}.card img{width:100%;height:160px;object-fit:contain}.card p{font-size:13px;margin:5px 0}.badge{padding:5px 11px;border-radius:14px;background:#dbe9df;display:inline-block}a{color:#21634c}.notice{background:#fbf2de;border-radius:9px;padding:12px}.empty{padding:20px;background:#f0f3ed}button{background:#276148;color:white;border:0;border-radius:7px;padding:6px 12px;cursor:pointer}@media(max-width:650px){main{padding:12px}header,.panel,section{padding:16px}.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.query{gap:12px}.query img{width:100px;height:100px}h1{font-size:27px}}</style><main><header><span class="badge">本地模型 · 1250 张公开测试素材</span><h1>先看含义候选，再比较画风</h1><p>语义：本轮锁定的自研 Chinese-CLIP 模型。风格：作者 ALADIN-ViT 权重。计算结果预先保存在本页，不调用方舟。</p><div class="notice">语义分数不是同义概率。阈值只供试验，没有经过人工金标准校准；候选可能不符合聊天语境。预览模式只展示前十名供核对；阈值模式才做筛选。第二步只在第一步的同一候选池内排序，不保证存在真正同义项。</div><p><a href="本地训练与验证报告.html">训练验证报告</a> · <a href="前五名同义核对.html">逐图核对同义性</a></p></header><div class="panel"><div class="controls"><label>查询图 <select id="query"></select></label><label>查看方式 <select id="mode"><option value="preview">前十名预览 · 尚未确认同义</option><option value="gate">按测试阈值筛选</option></select></label><label>语义测试阈值 <input id="threshold" type="number" min="0" max="1" step=".01" value=".70" style="width:100px"></label></div><div class="query"><img id="source" alt="查询图"><div><h2 id="label"></h2><p id="meaning"></p><small id="meta"></small></div></div></div><section><h2>1 · 语义候选</h2><p id="eligible"></p><div id="semantic" class="grid"></div></section><section><h2>2 · 同一候选池中的风格差异排序</h2><p>按 1 − cos(ALADIN) 从大到小排列；数值越大，模型认为画风越不同。这里只展示前十名。</p><div id="style" class="grid"></div></section></main><script>const rows=__ROWS__,excluded=__EXCLUDED__;const N=rows.length;function decode(s){const raw=atob(s),a=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)a[i]=raw.charCodeAt(i);return new Int16Array(a.buffer)}const sem=decode('__SEM__'),sty=decode('__STYLE__');const base='../sticker-codex-local-20261118/images/';const $=s=>document.querySelector(s);rows.forEach((r,i)=>{const o=document.createElement('option');o.value=i;o.textContent=r.id+' · '+r.text;$('#query').append(o)});function draw(container,indices,q){container.replaceChildren();if(!indices.length){const p=document.createElement('p');p.className='empty';p.textContent='当前阈值下没有合格候选；系统没有自动放宽条件。';container.append(p);return}indices.slice(0,10).forEach((j,k)=>{const r=rows[j],card=document.createElement('article');card.className='card';const img=document.createElement('img');img.src=base+r.id+'.png';img.alt=r.id;const title=document.createElement('strong');title.textContent=(k+1)+' · '+r.id;const p=document.createElement('p');p.textContent=r.text;const score=document.createElement('p');score.textContent='语义 '+(sem[q*N+j]/10000).toFixed(3)+' · 风格差异 '+(sty[q*N+j]/10000).toFixed(3);const btn=document.createElement('button');btn.textContent='以此查询';btn.onclick=()=>{$('#query').value=j;render();window.scrollTo({top:0})};card.append(img,title,p,score,btn);container.append(card)})}function render(){const q=Number($('#query').value),r=rows[q],threshold=Number($('#threshold').value),preview=$('#mode').value==='preview';$('#threshold').disabled=preview;if(!Number.isFinite(threshold)||threshold<0||threshold>1){$('#eligible').textContent='阈值须在0到1之间';return}$('#source').src=base+r.id+'.png';$('#label').textContent=r.id;$('#meaning').textContent='AI含义标签：'+r.text;$('#meta').textContent='划分：'+r.split+' · 标签：'+(r.quality==='clear'?'较明确':r.quality==='uncertain'?'待核查':'历史机器标签');const skip=new Set(excluded[r.id]||[]);let candidates=[];for(let j=0;j<N;j++)if(j!==q&&!skip.has(rows[j].id)&&(preview||sem[q*N+j]/10000>=threshold))candidates.push(j);if(preview)candidates.sort((a,b)=>sem[q*N+b]-sem[q*N+a]||a-b),candidates=candidates.slice(0,10);$('#eligible').textContent=preview?'候选预览：语义排名前十，但尚未确认同义。风格排序仅在这十张内进行。':'当前有 '+candidates.length+' 张候选；按语义分数排序，显示前十张。';draw($('#semantic'),[...candidates].sort((a,b)=>sem[q*N+b]-sem[q*N+a]||a-b),q);draw($('#style'),[...candidates].sort((a,b)=>sty[q*N+b]-sty[q*N+a]||sem[q*N+b]-sem[q*N+a]||a-b),q)}$('#mode').onchange=render;$('#query').onchange=render;$('#threshold').oninput=render;render();</script></html>'''
page=page.replace('__ROWS__',json.dumps(meta,ensure_ascii=False).replace('</','<\\/')).replace('__EXCLUDED__',json.dumps(exclude)).replace('__SEM__',encode(semantic)).replace('__STYLE__',encode(distance))
(out/'本地检索测试.html').write_text(page);print(json.dumps({'page_bytes':len(page.encode()),'images':len(rows)}))
